```python
def unique(xs):
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
```

```python
def sum_positive(xs):
    return sum(x for x in xs if x > 0)
```

```python
def safe_div(a, b):
    if b == 0:
        return None
    return a / b
```

```python
def flatten_one(xss):
    result = []
    for x in xss:
        if isinstance(x, list):
            result.extend(x)
        else:
            result.append(x)
    return result
```

```python
def sign(x):
    if x > 0:
        return 1
    elif x < 0:
        return -1
    else:
        return 0
```
